"""Portable written report and presentation, populated from completed outputs."""
import base64
from html import escape
import json
from pathlib import Path
import pandas as pd
from .paths import ROOT
from .reporting import conclusion_text, METHODS

def summary_pdf():
    from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,Table,TableStyle,Image
    from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import letter
    from reportlab.lib.enums import TA_LEFT
    path=ROOT/"report/Paper67_Replication_Report.pdf"
    styles=getSampleStyleSheet();styles.add(ParagraphStyle(name="ResearchBody",fontName="Helvetica",fontSize=9.5,leading=13.5,spaceAfter=8))
    styles.add(ParagraphStyle(name="ResearchTitle",fontName="Helvetica-Bold",fontSize=23,leading=28,spaceAfter=16,textColor=colors.HexColor('#172e43')))
    styles.add(ParagraphStyle(name="ResearchSmall",fontName="Helvetica",fontSize=8,leading=11,spaceAfter=5))
    story=[]
    def para(text,style="ResearchBody"):story.append(Paragraph(text,styles[style]))
    def title(text):para(text,"ResearchTitle")
    def fig(relative,width=480):
        from PIL import Image as PILImage
        p=ROOT/relative
        with PILImage.open(p) as image:w,h=image.size
        story.append(Image(str(p),width=width,height=width*h/w));story.append(Spacer(1,8))
    def table(df,widths=None):
        data=[list(df.columns)]+[[str(x) for x in row] for row in df.itertuples(index=False,name=None)]
        t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTNAME',(0,1),(-1,-1),'Helvetica'),
            ('FONTSIZE',(0,0),(-1,-1),7.5),('LEADING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),3),
            ('TOPPADDING',(0,0),(-1,-1),3),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6edf2')),
            ('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#9dabb5')),('VALIGN',(0,0),(-1,-1),'TOP')]))
        story.append(t);story.append(Spacer(1,10))
    manifest=json.loads((ROOT/"report/execution_manifest.json").read_text())
    trial_count=manifest['config']['random_search_trials']
    coverage=pd.read_csv(ROOT/"results/replication/tables/data_coverage.csv")
    title('Slow Momentum with Fast Reversion')
    para('IEOR 4576 - Executed replication<br/>Enze Hu (eh3203) and Jinrui Hu (jh5260)',"Heading2")
    para('Wood, Roberts &amp; Zohren (2022), arXiv:2105.13727v3',"ResearchSmall")
    para('<b>Research question.</b> Does adding online Gaussian-process changepoint location and severity to a Deep Momentum Network improve out-of-sample risk-adjusted returns, and does any gain survive trading costs?')
    para(f'<b>Scope.</b> This is an executed WRDS adaptation of the original 50-futures study, with {trial_count} search candidates per model/window. It uses real historical settlements and fitted models. Pinnacle histories and exact session/roll conventions are not available, so numerical identity is not claimed.')
    for p in conclusion_text().split('\n\n'):para(escape(p))
    para(f'<b>Evidence.</b> {len(coverage)} mapped instruments, {coverage.raw_rows.sum():,} raw contract-day observations and {coverage.feature_days.sum():,} feature rows. Completed model/window experiments: {manifest["completed_experiments"]}; random-search fits: {manifest["completed_trials"]}.')
    para('The professor\'s feedback on reversal costs and futures rolls is addressed after the original-style gross experiments. All reported tables and figures are generated by reusable Python modules, with an executed notebook and one-command rebuild.')
    story.append(PageBreak())
    title('Methodology and chronology')
    for text in [
        '<b>Returns and rolls.</b> Five-business-day calendar roll before vendor notice/last-trade dates; select the nearest maturity using prices known at the decision date. Compute P&amp;L within the held contract, never across a near/far price difference. Missing composite calendars for three markets use the vendor\'s same-month pit-contract schedule. Causal stale settlement marks are counted in the coverage table; these are valuations rather than executable fills.',
        '<b>Features.</b> Execute the preserved author feature functions with pandas API compatibility changes: normalized 1/21/63/126/252-session returns and three MACD pairs, price-index EWM winsorization at five standard deviations, and 60-session EWM volatility. The original-style labels are returns of the winsorized index; raw-return tradability sensitivity is separate.',
        '<b>GP-CPD.</b> Independently fit stationary and changepoint Matérn 3/2 GP kernels on every trailing 10/21/63/126/252-session window. Use maximum 200 L-BFGS-B iterations and stationary-parameter initialization of the CP model. Exact state-space likelihood evaluation matches the dense covariance. Severity is sigmoid(NLML_M - NLML_CP); relative location follows the author code.',
        '<b>LSTM.</b> Stateless 63-step LSTM, tanh positions, input/output dropout, pooled negative Sharpe loss, Adam, parameter-wise gradient clipping and output max-norm. Non-overlapping training/validation sequences, chronological per-instrument 90/10 split, purged boundary labels, maximum 300 epochs and patience 25. The CPU/Metal PyTorch port preserves these components, with backend numerical differences disclosed.',
        f'<b>Model selection.</b> {trial_count} distinct deterministic random draws from the published hyperparameter grid per model/window. CPD horizon selection uses only pre-test validation loss. One complete search repetition, base seed 67; repeated-seed robustness is not claimed. Compatible earlier CPU candidates retain their original provenance.',
        '<b>Backtest.</b> Expand training from 1990. Main OOS windows: 1995-1999, 2000-2004, 2005-2009, 2010-2014, 2015-2019. A separate pre-2020 refit scores 2020. Exclude the one-year 2020 window from the five-window exhibit means. Eligibility uses prior validation availability and Appendix A\'s first-test dates.',
        '<b>Portfolio.</b> Equal 1/N contribution across eligible instruments, with per-asset 15% annualized ex-ante risk scaling. Calendar differences contribute cash on unavailable-market dates. No hindsight volatility scaling is used for raw output; Exhibit 4 uses a single author-style factor targeting 15% mean window volatility; this is ex-post presentation only.'
    ]:para(text)
    story.append(PageBreak())
    title('Exhibits 3 and 4')
    for exhibit,label in [(3,'Raw signal output'),(4,'Ex-post 15% mean-window volatility rescaling')]:
        para(label,"Heading2");df=pd.read_csv(ROOT/f"results/replication/tables/exhibit_{exhibit}.csv")
        out=pd.DataFrame({'Strategy':df.strategy,'CAGR':df.annual_return.map('{:.2%}'.format),'Vol.':df.annual_volatility.map('{:.2%}'.format),
            'Sharpe':df.sharpe.map('{:.3f}'.format),'MDD':df.max_drawdown.map('{:.2%}'.format)})
        table(out,[200,70,70,70,70])
    para('All entries average the corresponding metric across the five main OOS windows. Full downside deviation, Sortino, Calmar, hit rate and profit/loss ratios are in the executed notebook and CSV tables. The separate 2020 test is reported in the regime diagnostics.',"ResearchSmall")
    story.append(PageBreak())
    title('Trading costs and futures rolls')
    fig('results/replication/figures/transaction_costs.png',465)
    para('Appendix C charges one-way traded-notional costs, including initial entry, exit, reversals and volatility-driven resizing. The 2.5-bps reference addresses the graded-proposal feedback. It is a scenario; daily settlements do not identify spreads, impact or capacity.')
    ext=pd.read_csv(ROOT/'results/extension/tables/roll_costs.csv')
    sub=ext[ext.cost_bps.eq(2.5)&ext.scenario.eq('raw returns plus rolls')]
    sub=sub[sub.strategy.isin(['TSMOM w=0','LSTM','LSTM-CPD-21','LSTM-CPD-63','LSTM-CPD-Optimised'])]
    out=pd.DataFrame({'Raw-return + roll scenario':sub.strategy,'Net Sharpe':sub.sharpe.map('{:.3f}'.format),
        'Turnover/year':sub.annual_turnover.map('{:.1f}'.format),'Roll extra/year':sub.annual_roll_extra.map('{:.1f}'.format)})
    table(out,[200,85,95,100])
    para('Both legs of a roll incur fees. A futures roll does not exchange the full principal of either contract: marking the same contract over each return interval prevents the near/far basis from becoming a fictitious cash flow. Positions are expressed in fractional risk-scaled notional, not integer contracts. A one-session signal delay and break-even costs are also reported.')
    story.append(PageBreak())
    title('Risk, interpretation and reproducibility')
    fig('results/replication/figures/regime_sensitivity.png',420)
    para('Regime sensitivity and drawdowns are reported alongside the aggregate Sharpe ratios. The 2020 column is a separate one-year test. A paired 63-session moving-block bootstrap measures conditional return-series uncertainty, not training-seed or model-selection uncertainty.')
    para('<b>Limitations.</b> WRDS replaces Pinnacle; several markets start later than the paper, NR ends in 2015, and the euro has no pre-euro extension. Local-currency return normalization, stale marks, idealized close execution and one search repetition limit numerical comparability. No separate MACD ablation or measured market-impact calibration is claimed.')
    para('<b>Rebuild.</b> From the prepared project environment, run <font name="Courier">make reproduce</font>. The main configuration uses the published 50-candidate search budget. Use <font name="Courier">make fresh</font> to train all candidates from random initialization.')
    para('Notebook: report/Paper67_Original_Study_Replication.ipynb<br/>Tables and figures: results/replication/ and results/extension/<br/>Provenance: report/execution_manifest.json, UPSTREAM.json and raw WRDS manifests',"ResearchSmall")
    para('Sources: Wood, Roberts &amp; Zohren (2022), arXiv:2105.13727v3; kieranjwood/slow-momentum-fast-reversion; LSTM/CPD components of kieranjwood/trading-momentum-transformer. Course guidelines and graded proposal were supplied locally. Author MIT licenses are preserved.',"ResearchSmall")
    def footer(canvas,doc):
        canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#65717b'))
        canvas.drawString(54,28,'IEOR 4576 | Paper 67 | WRDS adaptation');canvas.drawRightString(558,28,str(doc.page))
    SimpleDocTemplate(str(path),pagesize=letter,leftMargin=54,rightMargin=54,topMargin=48,bottomMargin=46).build(story,onFirstPage=footer,onLaterPages=footer)
    return path

def presentation_html():
    trial_count=json.loads((ROOT/'report/execution_manifest.json').read_text())['config']['random_search_trials']
    def image(relative):
        data=base64.b64encode((ROOT/relative).read_bytes()).decode()
        return f'<img src="data:image/png;base64,{data}" alt="Executed research results">'
    def table(df):return df.to_html(index=False,border=0,classes='data')
    comparison=pd.read_csv(ROOT/'results/replication/tables/published_comparison.csv')
    comp=comparison[['strategy','sharpe_published','sharpe_reproduced']].copy();comp.columns=['Strategy','Published Sharpe','WRDS Sharpe']
    for c in comp.columns[1:]:comp[c]=comp[c].map(lambda x:f'{x:.3f}')
    coverage=pd.read_csv(ROOT/'results/replication/tables/data_coverage.csv')
    sections=[('Slow Momentum with Fast Reversion',f'<p class="subtitle">Wood, Roberts &amp; Zohren (2022)<br>Enze Hu · Jinrui Hu · IEOR 4576</p><p>{escape(conclusion_text().split(chr(10)+chr(10))[0])}</p><p class="note">Executed WRDS adaptation. {trial_count} search trials per model/window; the original paper specifies 50.</p>'),
        ('Data and research design',f'<p>50 Appendix A instruments · {coverage.raw_rows.sum():,} raw contract-day observations · {coverage.feature_days.sum():,} feature rows</p><ul><li>1990–2020 target; vendor coverage differences disclosed</li><li>Same-contract returns, calendar rolls and causal settlement marks</li><li>Five main expanding OOS windows, plus a separate 2020 test</li><li>Per-instrument 90/10 chronological split; boundary labels purged</li></ul>'),
        ('LSTM with online GP changepoint features','<ul><li>Original author return and MACD feature functions</li><li>Stationary Matérn 3/2 GP versus sigmoid changepoint GP</li><li>Daily CPD severity and location at 10/21/63/126/252 sessions</li><li>Stateless 63-step LSTM; tanh position and negative Sharpe loss</li><li>Validation selects hyperparameters and the CPD horizon</li></ul>'),
        ('Published and reproduced results',table(comp)),
        ('Gross performance and risk scaling',image('results/replication/figures/wealth_comparison.png')),
        ('Transaction costs',image('results/replication/figures/transaction_costs.png')+'<p class="note">One-way bps of traded notional; reversals pay twice. The red line is the professor’s 2.5-bps scenario.</p>'),
        ('Futures rolls and execution sensitivity',image('results/extension/figures/roll_and_execution_costs.png')+'<p class="note">The near/far price gap is not a cash flow. Charge both roll legs, evaluate raw returns and delay the signal by one session.</p>'),
        ('Regime sensitivity',image('results/replication/figures/regime_sensitivity.png')),
        ('Conclusions and reproducibility',''.join('<p>'+escape(p)+'</p>' for p in conclusion_text().split('\n\n')[:2])+'<p class="note">Limits: different vendor and rolls, one search repetition, idealized daily execution, no measured impact model.</p><pre>make reproduce</pre>')]
    css='''*{box-sizing:border-box}body{margin:0;background:#e8edf1;color:#172e43;font-family:Arial,sans-serif}article{display:none;background:white;width:1280px;height:720px;padding:58px 72px;position:relative;overflow:auto}article.active{display:block}h1{font-size:42px;line-height:1.1;margin:0 0 30px}p,li{font-size:25px;line-height:1.45}li{margin-bottom:18px}p.subtitle{font-size:28px;color:#52697a}.note{font-size:19px;color:#52616c}img{display:block;max-width:1136px;max-height:500px;object-fit:contain;margin:auto}.data{border-collapse:collapse;width:100%;font-size:20px}.data th,.data td{text-align:left;padding:7px 13px;border-bottom:1px solid #dce4ea}.data th{background:#e6edf2}pre{font-size:25px;background:#eef2f5;padding:15px}footer{position:absolute;bottom:16px;left:72px;right:72px;font-size:15px;color:#65717b}nav{padding:12px;font-size:16px}button{font-size:16px;margin-right:8px}a{color:#2769a0}@media print{nav{display:none}article{display:block!important;page-break-after:always;width:100%;height:7.5in}body{background:white}@page{size:13.333in 7.5in;margin:0}}'''
    parts=[]
    for i,(title,body) in enumerate(sections):
        parts.append(f'<article class="{"active" if i==0 else ""}"><h1>{escape(title)}</h1>{body}<footer>{i+1}/{len(sections)} · Source: <a href="https://arxiv.org/abs/2105.13727">Wood et al. (2022)</a> and saved WRDS experiments</footer></article>')
    js="let i=0;const slides=[...document.querySelectorAll('article')];function move(n){slides[i].classList.remove('active');i=(i+n+slides.length)%slides.length;slides[i].classList.add('active')}document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key))move(1);if(['ArrowLeft','PageUp'].includes(e.key))move(-1)})"
    (ROOT/'report/Research_Presentation.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Paper 67 Research Presentation</title><style>'+css+'</style><nav><button onclick="move(-1)">Previous</button><button onclick="move(1)">Next</button>Use arrow keys; print for all slides</nav>'+''.join(parts)+'<script>'+js+'</script></html>')

def deliver():
    summary_pdf();presentation_html()
